from typing import List, Dict, Any

def get_query_responses(queries: List[Dict[str, Any]]) -> Dict[str, str]:
    """
    Given a list of query-response dictionaries, build and return a mapping
    of "Name:Type" -> ZenResponseTag.

    A single item is expected to look like:
        {
            "Query": {
                "Name": "<name>",
                "Type": "<type>"
            },
            "ZenResponseTag": "<response tag>"
        }

    Items lacking a usable ZenResponseTag (missing / None / empty string) are ignored.
    """
    result: Dict[str, str] = {}

    for item in queries:
        # Guard against missing or malformed structures
        if not isinstance(item, dict):
            continue

        query_info = item.get("Query", {})
        if not isinstance(query_info, dict):
            continue

        name = query_info.get("Name")
        qtype = query_info.get("Type")
        tag = item.get("ZenResponseTag")

        # Include only if all required parts are present and tag is truthy
        if name and qtype and tag:
            result[f"{name}:{qtype}"] = str(tag)

    return result

def get_lat_lon(exif_data):
    """
    Extract the latitude and longitude in decimal degrees from an EXIF dictionary.

    Parameters
    ----------
    exif_data : dict
        Dictionary returned by an EXIF parser (e.g. PIL.Image._getexif()).

    Returns
    -------
    tuple
        (latitude, longitude) as floats.  
        If either coordinate cannot be determined, returns (None, None).
    """

    # Helper ---------------------------------------------------------------
    def _to_degrees(val):
        """
        Convert various EXIF GPS formats to decimal degrees.

        - If *val* is already a float → returned as-is.
        - If *val* is an (deg, min, sec) iterable → converted to degrees.
        - If *val* contains rationals like (num, den) → those are evaluated.
        """
        if val is None:
            return None

        # Already a single real number
        if isinstance(val, (float, int)):
            return float(val)

        # Try to treat as (deg, min, sec)
        try:
            deg, minute, sec = val
        except (TypeError, ValueError):
            return None  # Unable to decipher

        def _r(x):
            """Evaluate a potential (num, den) rational."""
            if isinstance(x, (float, int)):
                return float(x)
            try:
                num, den = x
                return float(num) / float(den)
            except (TypeError, ValueError, ZeroDivisionError):
                return float(x)  # Fallback

        return _r(deg) + _r(minute) / 60.0 + _r(sec) / 3600.0

    # ---------------------------------------------------------------------
    if not isinstance(exif_data, dict):
        return (None, None)

    gps = exif_data.get("GPSInfo")
    if not isinstance(gps, dict):
        return (None, None)

    # Fetch raw values
    lat_val = gps.get("GPSDestLatitude")
    lat_ref = gps.get("GPSDestLatitudeRef")
    lon_val = gps.get("GPSDestLongitude")
    lon_ref = gps.get("GPSDestLongitudeRef")

    if None in (lat_val, lat_ref, lon_val, lon_ref):
        return (None, None)

    # Convert to decimal degrees
    lat = _to_degrees(lat_val)
    lon = _to_degrees(lon_val)

    if None in (lat, lon):
        return (None, None)

    # Apply sign according to reference
    if str(lat_ref).upper() == "S":
        lat = -lat
    if str(lon_ref).upper() == "W":
        lon = -lon

    return (lat, lon)

