from typing import Any, Dict, List, Union

def pluck(node: Union[Dict, List, Any], path: str) -> Any:
    """
    Extract a nested value from `node` (a dict or list) following `path`.

    Path syntax:
        • Segments are separated by dots:  "a.b.c"  or  "items.0.name"
        • A segment addressing a list index must be a valid integer string.

    Behaviour:
        • If `path` is an empty string, the original `node` is returned.
        • If a segment cannot be resolved (missing key, bad index, wrong type),
          the function returns None.
    """

    # If node is not traversable or no path requested, return node itself
    if not isinstance(node, (dict, list)) or path == "":
        return node

    segments = path.split(".")
    current: Any = node

    for seg in segments:
        # Skip empty segments caused by consecutive dots, if any
        if seg == "":
            continue

        if isinstance(current, dict):
            # dictionary lookup
            if seg in current:
                current = current[seg]
            else:
                return None

        elif isinstance(current, list):
            # list/array lookup via integer index
            try:
                idx = int(seg)
            except ValueError:
                return None   # segment is not a valid integer
            if 0 <= idx < len(current):
                current = current[idx]
            else:
                return None   # index out of range

        else:
            # Current node is neither dict nor list, but path still has segments
            return None

    return current

