class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def insert_to_bst(root: Node, data: int) -> Node:
    """
    Inserts `data` into the Binary Search Tree rooted at `root`
    and returns the (possibly new) root of the tree.
    """
    # If the tree is empty, the new node becomes the root
    if root is None:
        return Node(data)

    current = root
    while True:
        # Go to the left subtree
        if data < current.data:
            if current.left is None:
                current.left = Node(data)
                break
            current = current.left
        # Go to the right subtree (data >= current.data)
        else:
            if current.right is None:
                current.right = Node(data)
                break
            current = current.right

    return root

def is_isomorphic(s: str, t: str) -> bool:
    """
    Determine whether two strings are isomorphic.

    Two strings s and t are isomorphic if there exists a bijection between the
    characters of s and the characters of t such that replacing characters in
    s with their mapped counterparts yields t (and vice-versa).

    Rules implemented:
    1. If either string is empty, return True (per problem statement).
    2. Otherwise, if the strings differ in length, they cannot be isomorphic.
    3. Maintain two dictionaries to ensure a one-to-one (bijection) mapping:
       - map_s_to_t: char in s  -> char in t
       - map_t_to_s: char in t  -> char in s
    4. Iterate through the characters of both strings simultaneously,
       checking and updating the mappings.
    """
    # Rule 1: Empty-string shortcut
    if not s or not t:
        return True

    # Rule 2: Lengths must match for non-empty strings
    if len(s) != len(t):
        return False

    map_s_to_t = {}
    map_t_to_s = {}

    for ch_s, ch_t in zip(s, t):
        # Check existing mapping from s to t
        if ch_s in map_s_to_t:
            if map_s_to_t[ch_s] != ch_t:
                return False
        else:
            map_s_to_t[ch_s] = ch_t

        # Check existing mapping from t to s
        if ch_t in map_t_to_s:
            if map_t_to_s[ch_t] != ch_s:
                return False
        else:
            map_t_to_s[ch_t] = ch_s

    return True

from typing import Any, Tuple, Optional

def validate_and_clean(value: Any) -> Tuple[bool, Optional[bool]]:
    """
    Validate and normalise a value to a boolean.

    Returns
    -------
    Tuple[bool, Optional[bool]]
        • First element: True if the value can be interpreted as a boolean, else False.  
        • Second element: The normalised boolean value when valid, otherwise None.
    """
    # 1. Already a proper boolean
    if isinstance(value, bool):
        return True, value

    # 2. Numeric types (bool is a subclass of int, already handled above)
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        if value == 1:
            return True, True
        if value == 0:
            return True, False
        return False, None

    # 3. Strings that can be interpreted as booleans
    if isinstance(value, str):
        value_stripped = value.strip().lower()

        truthy = {"true", "t", "yes", "y", "1", "on"}
        falsy  = {"false", "f", "no", "n", "0", "off"}

        if value_stripped in truthy:
            return True, True
        if value_stripped in falsy:
            return True, False
        return False, None

    # 4. Anything else is invalid
    return False, None

