import math

def check_number_properties(num: int) -> str:
    """
    Determine whether the given integer is (1) divisible by 3, (2) a perfect square,
    and return the appropriate descriptive string.
    """
    # Check divisibility by 3
    divisible_by_3 = (num % 3 == 0)

    # Check if it's a perfect square: only meaningful for non-negative integers
    if num >= 0:
        root = math.isqrt(num)          # integer square root
        is_perfect_square = (root * root == num)
    else:
        is_perfect_square = False       # negative numbers cannot be perfect squares

    # Craft the response based on the two boolean properties
    if divisible_by_3 and is_perfect_square:
        return 'The number is divisible by 3 and is a perfect square.'
    elif divisible_by_3 and not is_perfect_square:
        return 'The number is divisible by 3 but is not a perfect square.'
    elif is_perfect_square and not divisible_by_3:
        return 'The number is a perfect square but not divisible by 3.'
    else:
        return 'The number is not divisible by 3 nor is it a perfect square.'

