import random

def generate_random_number() -> int:
    """
    Generates and returns a random 8-digit integer (inclusive range 10000000–99999999).
    """
    return random.randint(10_000_000, 99_999_999)

from typing import Any, List

def shift_and_sort(lst: List[Any], num: int) -> List[Any]:
    """
    Shift `lst` to the right by `num` positions (circularly) and then sort it.

    Rules for sorting:
        • Numeric values (int, float, complex) come first, in ascending order.
          – complex numbers are compared by their magnitude (abs).
        • Non-numeric, *collection* values (list / tuple / set / dict) are
          ordered by the numeric **sum** of their contents
          (dicts use their values).
        • Custom objects are compared by their `.attribute` value
          if that attribute exists.
        • Strings are ordered lexicographically.
        • Anything that does not match the above falls to the end.

    If `num` is negative, or larger than the list length, an empty list is
    returned.
    """
    # -------------------------- guard clauses -------------------------- #
    n = len(lst)
    if num < 0 or num > n:
        return []
    if n == 0:                 # empty list ⇒ nothing to do
        return []

    # ----------------------------- shift ------------------------------- #
    num = num % n                          # circular shift
    shifted = lst[-num:] + lst[:-num] if num else lst[:]

    # -------------------------- helper: key ---------------------------- #
    def sort_key(item: Any):
        """
        Produce a tuple that Python can compare to establish ordering
        according to the specification above.
        """
        # 0) numeric ---------------------------------------------------- #
        if isinstance(item, (int, float)):
            return (0, item)                      # numeric value itself
        if isinstance(item, complex):
            return (0, abs(item))                 # magnitude for complex

        # 1) collections ------------------------------------------------ #
        if isinstance(item, dict):
            # try summing the dictionary's *values*
            try:
                return (1, sum(item.values()))
            except Exception:
                return (1, 0)

        if isinstance(item, (list, tuple, set)):
            try:
                return (1, sum(item))
            except Exception:
                return (1, 0)

        # 2) custom objects with `.attribute` --------------------------- #
        if hasattr(item, "attribute"):
            try:
                return (2, getattr(item, "attribute"))
            except Exception:
                return (2, 0)

        # 3) strings ---------------------------------------------------- #
        if isinstance(item, str):
            return (3, item)

        # 4) fallback --------------------------------------------------- #
        return (4, 0)

    # ----------------------------- sort -------------------------------- #
    return sorted(shifted, key=sort_key)

def is_cube_of_prime(b: int) -> bool:
    """
    Return True if `b` is the cube of a single prime number, False otherwise.
    Assumes b < 2000.
    """
    # Cubes are non–negative; negative or 0/1 cannot be cubes of a prime.
    if b < 8:           # 2^3 is the smallest prime cube
        return False

    # Helper to test primality (enough for n <= 12 here, but keep it general).
    def is_prime(n: int) -> bool:
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    # Since b < 2000, p^3 <= 1999  => p <= 12
    for p in range(2, 13):
        if is_prime(p) and p ** 3 == b:
            return True
    return False

from typing import List

def evaluate_expression(expression: str) -> float:
    """
    Evaluate an arithmetic expression that may contain the operators
    +, -, *, /, ^ and parentheses, observing the usual rules of precedence.

    The expression is assumed to be well-formed and to contain only
    non-negative integer literals.  Result is returned as a float.
    """

    # ------------------------------------------------------------------
    # 1) Tokeniser ------------------------------------------------------
    # ------------------------------------------------------------------
    # We allow numbers with several digits and we treat each operator or
    # parenthesis as a single-character token.
    def tokenize(expr: str) -> List[str]:
        tokens, num = [], []
        for ch in expr:
            if ch.isdigit():
                num.append(ch)
            else:
                # flush number when we meet a non-digit
                if num:
                    tokens.append(''.join(num))
                    num.clear()
                if ch in '+-*/^()':
                    tokens.append(ch)
                # spaces are simply skipped
        if num:                                 # final pending number
            tokens.append(''.join(num))
        return tokens

    # ------------------------------------------------------------------
    # 2) Shunting-Yard: infix  ->  postfix (RPN) ------------------------
    # ------------------------------------------------------------------
    precedence = {'^': 4, '*': 3, '/': 3, '+': 2, '-': 2}
    right_associative = {'^'}

    def infix_to_postfix(tokens: List[str]) -> List[str]:
        output, stack = [], []
        for tk in tokens:
            if tk.isdigit():                    # number
                output.append(tk)
            elif tk in precedence:              # operator
                while (stack and stack[-1] in precedence and
                       ((tk not in right_associative and
                         precedence[tk] <= precedence[stack[-1]]) or
                        (tk in right_associative and
                         precedence[tk] < precedence[stack[-1]]))):
                    output.append(stack.pop())
                stack.append(tk)
            elif tk == '(':
                stack.append(tk)
            elif tk == ')':
                while stack and stack[-1] != '(':
                    output.append(stack.pop())
                stack.pop()                     # discard '('
        while stack:
            output.append(stack.pop())
        return output

    # ------------------------------------------------------------------
    # 3) Evaluate postfix ----------------------------------------------
    # ------------------------------------------------------------------
    def eval_postfix(tokens: List[str]) -> float:
        stack: List[float] = []
        for tk in tokens:
            if tk.isdigit():
                stack.append(float(tk))
            else:
                right = stack.pop()
                left  = stack.pop()
                if tk == '+':
                    stack.append(left + right)
                elif tk == '-':
                    stack.append(left - right)
                elif tk == '*':
                    stack.append(left * right)
                elif tk == '/':
                    stack.append(left / right)
                elif tk == '^':
                    stack.append(pow(left, right))
        return stack[0] if stack else 0.0

    # ------------------------------------------------------------------
    # Tie everything together ------------------------------------------
    # ------------------------------------------------------------------
    postfix = infix_to_postfix(tokenize(expression))
    return eval_postfix(postfix)
